from lesson_helpers import *
from bs4 import BeautifulSoup
import re
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
def concept(k,title,p1,p2,ids):add('g25-'+k,title,'<p>'+p1+'</p><p>'+p2+'</p>',ids)
concept('definition','Un groupe de troubles, pas une maladie unique','G25 rassemble plusieurs phénomènes : tremblement, myoclonies, certaines chorées et certains tics, jambes sans repos et autres troubles précisés. Le même terme administratif ne choisit pas le traitement.','Décrire le mouvement et son contexte, rechercher une cause et une urgence, puis choisir le code applicable. Certaines maladies ou symptômes ressemblants sont classés ailleurs.',('CH-CIM','CH-CIM-BOUND','EU-TREMOR-PHENO'))
concept('phenotype','Phénotype : ce que l’on observe','Préciser type de mouvement, rythme, durée, régions, côté, conditions d’activation, chronologie et signes associés. Ajouter les symptômes que l’examen ne peut voir, comme besoin de bouger ou gêne sensitive.','Le phénotype oriente les examens mais n’établit pas toujours la cause. Une même étiologie peut produire plusieurs profils et plusieurs causes peuvent produire un profil proche.',('EU-TREMOR-PHENO','EU-MYO-NEURO','EU-RLS-DX'))
concept('etiology','Cause : relier des arguments concordants','Histoire familiale et médicale, médicaments, événements et signes associés permettent de cibler une hypothèse. Début aigu et confusion ne s’explorent pas comme une oscillation bilatérale stable depuis des années.','La famille négative ne supprime pas toute hérédité ; une association médicamenteuse n’est pas toujours une preuve d’imputabilité. Expliquer ce qui est certain, probable et encore à chercher.',('EU-CHOREA-DX','EU-CHOREA-CAUSE','EU-MYO-DX'))
concept('rest','Repos réellement soutenu','Pour caractériser un tremblement de repos, le membre doit être relâché et soutenu ; une main tenue en l’air maintient déjà une activité posturale. Décrire la condition de l’observation.','Un tremblement de repos ne suffit pas à lui seul à diagnostiquer Parkinson. Les autres signes, médicaments et contexte restent indispensables.',('EU-TREMOR-PHENO','CH-USZ-TREMOR'))
concept('posture','Maintien de posture et mouvement','Le tremblement postural apparaît lors d’un maintien contre la gravité ; le cinétique pendant le mouvement. Comparer aussi une tâche précise, car certaines manifestations dépendent d’une action ou d’une position.','Cette description prépare une hypothèse de syndrome. Elle ne prouve pas à elle seule une cause essentielle, médicamenteuse ou cérébelleuse.',('EU-TREMOR-PHENO',))
concept('intention','Oscillation à l’approche d’une cible','Le tremblement d’intention augmente typiquement lors de l’approche d’un but, par exemple au doigt-nez. Chercher les autres signes de coordination et distinguer une dysmétrie sans oscillation.','Un syndrome cérébelleux justifie une recherche de cause structurale, notamment par imagerie selon la recommandation. Toutes les intentions ne prouvent pas une même lésion ni un même traitement.',('EU-TREMOR-CEREB','CH-USZ-TREMOR'))
concept('essential','Critères du tremblement essentiel','La recommandation DGN/SNG 2022 décrit tremblement d’action bilatéral des membres supérieurs depuis au moins trois ans, sans autre syndrome neurologique défini. Une famille atteinte ou un effet de l’alcool peut soutenir mais n’est pas obligatoire.','Moins de trois ans : chercher notamment médicaments et hyperthyroïdie, documenter et réévaluer. Ce n’est pas une instruction d’attendre sans soins, ni une invitation à utiliser l’alcool.',('EU-TREMOR-ET',))
concept('etplus','Essentiel plus : des signes discrets','La catégorie essentiel plus décrit des signes supplémentaires discrets insuffisants pour établir un autre syndrome, par exemple anomalies légères de marche en tandem ou signes dystoniques douteux.','Un parkinsonisme, une ataxie ou une dystonie clairement établis ne sont pas simplement absorbés dans cette étiquette. Décrire et réévaluer ; les études historiques regroupaient souvent ces profils.',('EU-TREMOR-ET',))
concept('drug','Médicament : dose, durée et chronologie','Reprendre les médicaments réellement pris, ceux reçus ailleurs, changements et arrêts. Antagonistes dopaminergiques, certains antiémétiques, agents dopaminergiques et de nombreuses autres substances peuvent contribuer.','Revoir la cause avec le prescripteur avant d’empiler des traitements. Un arrêt brutal peut être dangereux pour certains traitements ; une toxicité grave relève d’une prise en charge urgente adaptée.',('EU-CHOREA-CAUSE','EU-CBIP-AKA','EU-CBIP-URG','FI-SIFROL','FI-KEPPRA'))
concept('frequency','La fréquence aide sans décider seule','Une fréquence est un nombre d’oscillations par seconde. Plusieurs syndromes ont des plages qui se chevauchent ; la condition, le rythme, l’amplitude et les signes associés restent nécessaires.','Le profil rapide 13–18 Hz cohérent debout caractérise une situation particulière, le tremblement orthostatique primaire. On ne l’étend pas à tous les tremblements ou à toute instabilité.',('EU-TREMOR-PHENO','EU-TREMOR-ORTHO'))
concept('functional','Signes positifs d’un tremblement fonctionnel','Variabilité, modification par distraction et entraînement à une tâche rythmique controlatérale peuvent soutenir le diagnostic dans un ensemble concordant. Le spécialiste explique les signes et le raisonnement.','Une anxiété, une IRM normale ou un seul signe ne suffit pas. Une autre maladie neurologique peut coexister, et trouble fonctionnel n’est pas synonyme de simulation.',('EU-TREMOR-FUNC',))
concept('orthostatic','Instabilité liée à la station debout','Le tremblement orthostatique primaire survient dans les jambes debout, avec activité typique 13–18 Hz et cohérence élevée ; la station assise, couchée ou la marche peuvent soulager. L’examen et l’EMG doivent reproduire la condition avec sécurité.','Formes lentes et myoclonies orthostatiques sont distinctes. Ce n’est pas un diagnostic de jambes sans repos, ni une hypotension supposée sans évaluation.',('EU-TREMOR-ORTHO','EU-RLS-MIMIC'))
concept('positive','Myoclonie positive','Une contraction brève produit une secousse. Sa distribution, sa relation à l’action ou aux stimuli, et son évolution renseignent ; plusieurs niveaux de générateurs sont possibles.','La rythmicité n’est pas toujours absente et l’épilepsie n’est pas obligatoire. L’étiologie et, si nécessaire, la neurophysiologie déterminent la suite.',('EU-MYO-DX','EU-MYO-NEURO'))
concept('negative','Myoclonie négative et astérixis','Une interruption brève d’une activité musculaire en cours fait céder une posture. L’astérixis en est un exemple, notamment dans un contexte toxique ou métabolique.','Toutes les myoclonies négatives ne s’appellent pas astérixis. Distinguer interruption, faiblesse persistante et oscillation ; une confusion nouvelle impose une recherche urgente de cause.',('EU-MYO-DX','EU-MYO-NEURO'))
concept('emg','Électromyographie de surface','Des électrodes enregistrent les bouffées musculaires, leur durée et leurs relations. Choisir les muscles et la condition qui reproduit le phénomène est essentiel.','Durées et rythmes se chevauchent ; l’enregistrement ne livre pas seul la cause. Des techniques complémentaires et l’examen clinique sont parfois nécessaires.',('EU-MYO-NEURO','EU-TREMOR-ORTHO'))
concept('eeg','Coupler cerveau et muscles','Un EEG–EMG simultané recherche la relation temporelle entre secousse et activité corticale. Un rétromoyennage peut rendre visible un signal discret avec suffisamment d’événements de qualité.','Artefacts, médicaments et échantillonnage limitent l’interprétation. Un EEG bref normal n’exclut pas toutes les crises ni tous les générateurs corticaux ; G25.3 exclut l’épilepsie myoclonique.',('EU-MYO-NEURO','CH-CIM-BOUND'))
concept('chorea','Chorée : un profil irrégulier','Mouvements rapides, imprévisibles et irréguliers, parfois intégrés dans un geste apparemment volontaire. L’examen cherche aussi signes neurologiques, systémiques et histoire familiale.','Causes acquises, métaboliques, médicamenteuses et héréditaires sont possibles. Huntington et Sydenham ont des codes distincts ; une dose de traitement de Huntington ne devient pas un traitement de toutes les chorées.',('EU-CHOREA-DX','EU-CHOREA-CAUSE','CH-CIM-BOUND','FI-TIAPRIDAL'))
concept('tic','Tic : besoin et suppression variables','Tics moteurs ou vocaux, brefs et récurrents, souvent avec tension prémonitoire et possibilité de suppression transitoire. Ces caractéristiques varient selon âge et sévérité.','Ni absence de besoin rapporté chez un enfant ni suppression au cabinet ne tranche toute la question. Rechercher retentissement, comorbidités et causes ; Tourette ne relève pas de G25.6.',('EU-TICS-DX','EU-TICS-EXAM','CH-CIM-BOUND'))
concept('akathisia','Akathisie : une agitation à reconnaître','Difficulté à rester assis ou immobile, avec besoin de bouger et agitation intérieure. Le lien avec médicament et évolution aide à distinguer ce phénomène d’une simple anxiété ou de jambes sans repos.','La prédominance soir/nuit et le profil sensoriel du RLS ne sont pas obligatoires dans l’akathisie. Revoir la cause et la dose avec l’équipe ; les adjuvants ont des preuves et des risques variables.',('EU-CBIP-AKA','EU-RLS-MIMIC','FI-TIAPRIDAL'))
concept('rls','Jambes sans repos : diagnostic clinique','Le besoin de bouger au repos, soulagé par mouvement et à prédominance soir/nuit doit satisfaire les cinq critères, dont l’absence d’explication intégrale par une autre condition.','Une polysomnographie n’est pas obligatoire pour ce diagnostic. Crampes, neuropathie, gêne articulaire ou positionnelle peuvent imiter ou coexister ; distinguer les plaintes.',('EU-RLS-DX','EU-RLS-MIMIC','CH-HUG-RLS'))
concept('criteria','Les cinq critères ensemble','Besoin de bouger ; début ou aggravation au repos ; soulagement au moins partiel tant que le mouvement continue ; prédominance soir/nuit ; manifestations non entièrement expliquées par une autre condition.','Un score de sévérité n’est pas un diagnostic autonome. L’interview et les mots du patient, adaptés au développement chez l’enfant, restent nécessaires.',('EU-RLS-DX',))
concept('plms','Mouvements périodiques et trouble du sommeil','Les mouvements périodiques pendant le sommeil peuvent accompagner les jambes sans repos. Ils sont observés par un enregistrement du sommeil et ne sont pas la même chose qu’une envie consciente de bouger.','Un index polysomnographique seul ne suffit pas à définir une maladie PLMD à traiter. Le contexte, les plaintes et les autres troubles du sommeil doivent être pris en compte.',('EU-RLS-DX','EU-RLS-2026','CH-HUG-RLS'))
concept('iron','Fer : indication et bilan','Numération, ferritine et saturation de la transferrine sont utiles dans la démarche RLS. La recommandation discute supplémentation selon tableau clinique et bilan.','Ferinject exige une carence adulte confirmée et un oral insuffisamment efficace, impossible ou intoléré. Un code RLS ne suffit pas à administrer automatiquement du fer intraveineux.',('EU-RLS-IRON','FI-FERINJECT'))
concept('ferritin','Ferritine : un seuil contextualisé','La recommandation RLS 2024 utilise autour de 75 µg/L pour discuter le fer, avec des formulations ≤ dans le résumé et < dans le corps du texte. La saturation et le contexte complètent la lecture.','Ce n’est ni une mesure directe du fer cérébral ni une norme universelle suisse. Aux bornes, ne pas fabriquer une précision absente et vérifier l’ensemble du bilan et du produit envisagé.',('EU-RLS-IRON','EU-RLS-MECH','FI-FERINJECT'))
concept('augmentation','Augmentation sous dopaminergique','Début des symptômes avancé d’environ deux heures, propagation, intensité accrue ou effet plus court. La chronologie comparée au début du traitement est importante.','Ne pas augmenter automatiquement la dose. Revoir fer, imitateurs et traitement avec expertise ; un agoniste chronique peut devoir être réduit très lentement pour éviter un syndrome de sevrage.',('EU-RLS-AUG','FI-SIFROL'))
concept('prami','Pramipexole immédiat et RLS','La FI Sifrol prévoit 0,125 mg de sel une fois par jour deux à trois heures avant coucher, puis paliers de 0,125 mg tous les quatre à sept jours si besoin, maximum RLS 0,75 mg/jour et dose la plus faible utile.','La forme ER et les plafonds Parkinson ne s’importent pas au RLS. Vérifier rein, augmentation, somnolence/endormissement subit et pulsions ; l’hémodialyse est contre-indiquée.',('FI-SIFROL',))
concept('base','Sel et base : deux écritures à identifier','Dans la présentation lue, 0,125 mg de pramipexole sous forme de sel correspond à 0,088 mg de base. Les nombres du schéma RLS de ce cours sont exprimés en sel.','Une source étrangère ou une autre rubrique peut employer la base et des arrondis différents. Vérifier chaque force et formulation ; ne pas remplacer numériquement un nombre par l’autre ni harmoniser tous les arrondis.',('FI-SIFROL',))
concept('primidone','Primidone : usage et galénique','La DGN/SNG recommande la primidone pour l’essentiel, hors indication de la FI Mysoline qui concerne l’épilepsie. La tolérance initiale peut être mauvaise même à faible dose.','Le comprimé suisse de 250 mg est demi-sécable ; un très faible début discuté dans la guideline exige une formulation vérifiée, pas une division inventée. Risques de sédation, ataxie, induction et reproduction à expliquer.',('EU-TREMOR-TX','FI-MYSOLINE'))
concept('pregabalin','Prégabaline : efficacité discutée et FI suisse','Les indications Lyrica sont adultes et ne comprennent pas le RLS. La recommandation RLS décrit un usage hors indication ; le résumé italien 2026, dérivé de recommandations américaines, ne change pas ce statut.','La FI juillet 2026 exclut l’utilisation si clairance < 30 mL/min. Vérifier somnolence, dépendance et risque respiratoire avec opioïdes ; arrêt progressif individualisé sur semaines ou mois.',('FI-LYRICA','EU-RLS-TX','EU-RLS-2026'))
concept('sps','Syndrome de la personne raide','Raideur axiale/proximale, spasmes déclenchés et retentissement sur marche/chutes orientent. Le spectre peut être associé à une auto-immunité, mais le diagnostic relève d’un faisceau clinique spécialisé.','Électrophysiologie, anticorps et recherche de contexte auto-immun ou tumoral se discutent. Traitement symptomatique et immunitaire sont individualisés, avec preuves limitées pour plusieurs options.',('EU-SPS-DX','EU-SPS-MECH','EU-SPS-TX'))
concept('gad','GAD65 : enzyme et anticorps','GAD2 code une glutamate décarboxylase, isoforme GAD65, participant à la synthèse du GABA. Des anticorps anti-GAD65 sont associés à plusieurs contextes, dont certaines formes de personne raide.','Un résultat positif isolé ne constitue pas le diagnostic neurologique. Titre, clinique, électrophysiologie et parfois liquide cérébrospinal importent. L’immunomarquage PCP4 montré dans ce cours est différent.',('NORMAL-GAD2','EU-SPS-DX','IMG-PURKINJE'))
concept('urgent','Urgence : les signes associés changent le circuit','Début soudain avec déficit, confusion, convulsions ou trouble respiratoire exige une évaluation immédiate. Après médicaments, fièvre, rigidité ou clonus et instabilité autonome font rechercher une toxicité grave.','Un syndrome malin peut être atypique, sans rigidité nette ou avec fièvre modérée. Ne pas attendre tous les critères ; sécuriser et traiter avec l’équipe, en retrouvant produits, doses et chronologie.',('EU-MYO-DX','EU-CBIP-URG','FI-TIAPRIDAL'))
concept('follow','Suivi : fonction et sécurité','Répéter une tâche utile dans des conditions comparables, demander sommeil, autonomie, chutes et vécu. Documenter traitements et effets indésirables, pas seulement amplitude du mouvement.','Une réponse symptomatique ne prouve pas la cause. Nouveaux signes, symptômes plus précoces sous agoniste ou perte de tolérance imposent une réévaluation.',('EU-TREMOR-PHENO','EU-RLS-AUG','EU-SPS-TX','FI-SIFROL'))
concept('calculation','Dose déjà choisie, volume vérifié','Pour les gouttes orales Rivotril à 0,1 mg/goutte, une quantité déjà prescrite de 0,5 mg correspond à cinq gouttes. Pour Ferinject à 50 mg de fer/mL, 500 mg correspondent à 10 mL de produit avant dilution.','L’arithmétique ne choisit pas indication, dose, voie ou personne. Rivotril injectable est une autre formulation ; Ferinject injection et perfusion ont des plafonds en mg/kg différents, avec cumul hebdomadaire et surveillance.',('FI-RIVOTRIL','FI-FERINJECT'))
assert len(pops)==34
path=CH/'G25_a.html';txt=path.read_text();plain=BeautifulSoup(txt,'html.parser')
essential=[
 'Décrire le phénomène puis sa cause ; respecter les exclusions OFS avant de coder.',
 'G25 réunit des populations différentes ; aucune fréquence unique ne décrit le groupe.',
 'Générateur, circuit et effecteur expliquent des signes distincts sans mécanisme universel.',
 'Sécurité et cause traitable précèdent la classification complète.',
 'Une chronologie des symptômes et des prises réelles vaut mieux qu’une simple liste.',
 'Comparer repos soutenu, maintien, action et signes associés avec sécurité.',
 'Oscillation, secousse, chorée, tic, agitation et spasme ne sont pas synonymes.',
 'Appliquer les critères complets et dire le niveau de certitude.',
 'Choisir un examen capable de répondre à la question clinique.',
 'Comparer le profil complet et accepter que plusieurs troubles coexistent.',
 'Indication, formulation et population suisses encadrent le choix thérapeutique.',
 'Mesurer fonction et tolérance, et rechercher augmentation sous agoniste.',
 'Les décisions utiles relient signe, cause, produit et suivi.',
 'Une étiquette, un test isolé ou un calcul exact ne valide pas toute la conduite.'
]
extra=[
 'Exemple : une épilepsie juvénile myoclonique peut relever d’une indication Keppra, mais la nomenclature l’exclut de G25.3. Une indication de médicament ne doit donc pas être utilisée pour fabriquer le code.',
 'Une statistique sur un syndrome défini dans une cohorte ne s’additionne pas aux fréquences d’autres symptômes qui peuvent coexister. Donner population, méthode et date évite une fausse estimation nationale.',
 'Une myoclonie positive ajoute une activité ; une négative interrompt un maintien. Cette différence conduit à des enregistrements et causes possibles distincts, pas simplement à une graduation de sévérité.',
 'Confusion et secousses nouvelles après modification médicamenteuse changent la priorité. Décrire précisément le phénomène reste utile, mais ne doit pas retarder une recherche toxique ou métabolique urgente.',
 'Demander dernière prise, forme et évolution après chaque changement permet de tester une hypothèse. Une ordonnance ne prouve pas ce qui a réellement été administré, et une association temporelle reste à interpréter.',
 'Une main non soutenue n’est pas véritablement au repos. Une oscillation près d’une cible et une dysmétrie sans oscillation doivent être nommées séparément pour que la question d’imagerie soit correcte.',
 'L’envie de bouger au repos le soir relève d’un entretien clinique ; une activité rapide des jambes uniquement debout demande un autre raisonnement. Le soulagement par mouvement n’unifie pas toutes ces plaintes.',
 'Pour les jambes sans repos, le cinquième critère évite de classer une crampe ou une gêne articulaire comme syndrome. Une affection coexistante n’exclut pas le diagnostic si ses symptômes sont distingués.',
 'Une mesure hors de la condition déclenchante peut manquer le phénomène. Inversement, un résultat anormal sans question précise peut produire une attribution excessive. Expliquer ce que l’examen pourra changer.',
 'L’existence d’une neuropathie ou d’un trouble fonctionnel ne supprime pas automatiquement une autre affection. Décrire les arguments pour chaque hypothèse permet un plan de suivi plus utile que forcer une cause unique.',
 'Une recommandation d’efficacité et une autorisation suisse répondent à deux questions. Prégabaline pour RLS et primidone pour essentiel illustrent un usage hors indication, avec formulation, rein et risques à vérifier.',
 'Si les symptômes RLS commencent plus tôt sous agoniste, une escalade peut aggraver la situation. Reprendre l’heure de début, l’extension, le fer et les imitateurs puis planifier la conduite avec expertise.',
 'Une décision juste peut être de différer un médicament en recherchant une cause ou de réévaluer une formulation. Le succès ne se limite pas à faire disparaître visuellement un mouvement.',
 'Un volume peut être mathématiquement juste alors que le produit ou la voie est faux. De même, un anticorps positif et une image de référence ne fournissent pas seuls une indication d’immunothérapie.'
]
for i in range(1,15):
 q=plain.find(id=f'g25-{i}');ids=list(dict.fromkeys(''.join(str(x) for x in a.find_all(string=True)).split(' — ')[0] for a in q.select('a[data-reference-source]')));paras=[' '.join(str(x) for x in p.find_all(string=True)) for p in q.find_all('p',recursive=False) if 'src' not in p.get('class',[])][:2]
 add('g25-exp-'+str(i),'Comprendre — point '+str(i),'<p><b>Raisonnement.</b> '+extra[i-1]+'</p><p>'+essential[i-1]+'</p>'+''.join('<p>'+p+'</p>' for p in paras),ids)
 add('pareto-g25-'+str(i),'Essentiel — point '+str(i),'<p>'+essential[i-1]+'</p>'+key('Décrire, contextualiser et choisir une décision qui change les soins.'),ids)
 pattern=r'(<section class="ilot" id="g25-'+str(i)+r'"[^>]*><h2>)(.*?)(</h2>)';match=re.search(pattern,txt,re.S);assert match
 entry='<p>'+w('exp-'+str(i),'Comprendre ce point')+' <button class="pareto-btn ui" data-k="pareto-g25-'+str(i)+'">▲ Loi de Pareto — l’essentiel</button></p>';txt=txt[:match.end(3)]+entry+txt[match.end(3):]
cases=[('Une oscillation bilatérale ancienne','Une personne décrit quatre ans d’oscillations des mains pendant maintien et gestes, sans autre signe évident à l’histoire. Sa famille n’est pas atteinte.','Observer les conditions, faire l’examen complet et rechercher médicaments/thyroïde avant conclusion ; une famille négative n’exclut pas l’essentiel, et un effet d’alcool n’est ni requis ni un traitement.',('EU-TREMOR-ET','EU-TREMOR-PHENO')),('Secousses et confusion nouvelles','Une personne commence à lâcher des objets et paraît confuse après changement de traitement, dans un contexte d’atteinte rénale.','Évaluer rapidement la sécurité et les causes toxiques/métaboliques ; distinguer secousses positives et interruptions de maintien. Ne pas prescrire automatiquement un traitement d’épilepsie sans évaluation.',('EU-MYO-DX','EU-MYO-NEURO','FI-LYRICA')),('Les jambes plus tôt dans la journée','Sous agoniste chronique pour jambes sans repos, les symptômes commencent désormais deux heures plus tôt et touchent aussi les bras.','Penser augmentation, vérifier fer et imitateurs, revoir le traitement avec expertise. Ne pas augmenter automatiquement la dose ni interrompre brutalement un agoniste chronique sans plan.',('EU-RLS-AUG','FI-SIFROL')),('Un anticorps sans conclusion automatique','Une personne présente une raideur du tronc et des spasmes déclenchés ; un dosage anti-GAD65 revient positif.','Neurologie spécialisée : phénotype, titre, électrophysiologie et contexte immunitaire/tumoral. Un résultat seul et l’image PCP4 de référence ne justifient pas un protocole d’immunothérapie.',('EU-SPS-DX','EU-SPS-TX','IMG-PURKINJE'))]
for i,(title,p1,p2,refs) in enumerate(cases,1):add('g25-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice fictif original.</b></p><p>'+p1+'</p><p>'+p2+'</p>',refs)
quiz=[('Une polysomnographie est-elle indispensable à tout diagnostic de jambes sans repos ?','Non, le diagnostic repose sur cinq critères cliniques et les examens sont ciblés.','Oui, aucun diagnostic ne peut être posé sans cet examen.','Les mouvements périodiques du sommeil et les symptômes de jambes sans repos ne sont pas équivalents.','EU-RLS-DX'),('Des symptômes plus précoces sous agoniste imposent-ils une augmentation automatique de dose ?','Non, une augmentation des symptômes liée au traitement doit être recherchée.','Oui, c’est toujours la preuve que la dose est trop faible.','Revoir chronologie, extension, fer et traitement avec expertise ; planifier toute réduction chronique.','EU-RLS-AUG'),('La forme retard de pramipexole peut-elle remplacer librement la forme immédiate pour les jambes sans repos ?','Non, indication, formulation et schéma du produit doivent être vérifiés.','Oui, toute forme du même principe actif a le même schéma.','La forme retard a une indication parkinsonienne dans la monographie suisse lue.','FI-SIFROL'),('Un anti-GAD positif suffit-il à diagnostiquer le syndrome de la personne raide ?','Non, clinique et explorations spécialisées doivent être concordantes.','Oui, tout résultat positif impose immédiatement le même traitement.','Un marqueur isolé ne remplace pas le phénotype, le titre et la neurophysiologie.','EU-SPS-DX')]
q=''.join('<div class="quiz ui"><p>'+question+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for question,yes,no,ex,sid in quiz)
txt=txt.replace('</div></div>',sec('entrainement','S’entraîner : quatre décisions et quatre cas',q+'<p>'+' '.join(w('cas-'+str(i),'Cas '+str(i)) for i in range(1,5))+'</p>',('CH-PROFILES','CH-MEBEKO'))+'</div></div>',1);path.write_text(txt)
# A distinct GAD window is placed in the immune discipline, where its meaning is explained.
